const s = nb.get('temp_stats');
const card = (label, value, color) =>
  `<div style="background:white;border:1px solid #e5e7eb;border-radius:12px;padding:14px 16px;text-align:center;">
    <div style="font-size:12px;color:#6b7280;text-transform:uppercase;letter-spacing:.5px">${label}</div>
    <div style="font-size:1.6rem;font-weight:700;color:${color};margin-top:4px">${value}</div>
  </div>`;

return `
<div style="font-family:system-ui;padding:20px;background:#f8fafc;border-radius:16px;">
  <h3 style="margin:0 0 16px">Temperature Statistics</h3>
  <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:12px;">
    ${card('Mean', s.mean + '°C', '#3b82f6')}
    ${card('Median', s.median + '°C', '#6366f1')}
    ${card('Std Dev', '±' + s.std, '#f59e0b')}
    ${card('Min', s.min + '°C', '#06b6d4')}
    ${card('Max', s.max + '°C', '#ef4444')}
    ${card('Q1', s.q1 + '°C', '#8b5cf6')}
    ${card('Q3', s.q3 + '°C', '#8b5cf6')}
  </div>
</div>`;
